#!/usr/bin/env bash
# adopt.sh - adopt an EXISTING repo (not generated by project-init) into the
# documentation layer, without changing how the repo works today.
#
# Docs-only: never adds hooks, CI, ESLint, pre-push, or branch protection -
# those would break whatever flow/CI the repo already has. It only
# documents the CURRENT reality (a "Workflow contract" reflecting what's
# actually enforced today, which may be "nothing") and may RECOMMEND
# stronger enforcement in its output.
#
# Usage: adopt.sh --dir <repo> [--dry-run] [--json]
#
# Must not modify the repo's current working tree or branch - it only
# writes into the directory given. The caller is expected to pass a git
# worktree checked out from the default branch (see SKILL.md "Adopting an
# existing repo"), not the user's working checkout.
#
# Idempotent: a second run makes no changes.
set -euo pipefail

usage() {
  cat <<'EOF'
Usage: adopt.sh --dir <repo> [--dry-run] [--json]

  --dir       path to the existing repo to adopt (required)
  --dry-run   detect and print the plan, write nothing
  --json      emit the detection summary (and, on a real run, the actions
              taken) as JSON instead of human-readable text
EOF
}

DIR=""
DRY_RUN=0
JSON=0

while [ $# -gt 0 ]; do
  case "$1" in
    --dir) DIR="$2"; shift 2 ;;
    --dry-run) DRY_RUN=1; shift ;;
    --json) JSON=1; shift ;;
    -h|--help) usage; exit 0 ;;
    *) echo "Unknown arg: $1" >&2; usage; exit 1 ;;
  esac
done

[ -n "$DIR" ] || { echo "Error: --dir is required" >&2; usage; exit 1; }
DIR="$(cd "$DIR" 2>/dev/null && pwd)" || { echo "Error: --dir does not exist" >&2; exit 1; }
[ -d "$DIR/.git" ] || git -C "$DIR" rev-parse --git-dir >/dev/null 2>&1 || { echo "Error: $DIR is not a git repo" >&2; exit 1; }

SKILL_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
COMMON_DECISIONS_DIR="$SKILL_DIR/templates/common/docs/decisions"
DATE="$(date +%Y-%m-%d)"

cd "$DIR"

ACTIONS=()
DEVIATIONS=()
RECOMMENDATIONS=()
note() { ACTIONS+=("$1"); }
deviation() { DEVIATIONS+=("$1"); }

# ---------------------------------------------------------------------------
# Detection
# ---------------------------------------------------------------------------

OWNER=""
REPO=""
origin_url="$(git config --get remote.origin.url 2>/dev/null || true)"
if [ -n "$origin_url" ]; then
  owner_repo="$(printf '%s' "$origin_url" \
    | sed -e 's#^git@[^:]*:##' -e 's#^[a-zA-Z]*://[^/]*/##' -e 's#\.git$##' -e 's#/$##')"
  OWNER="${owner_repo%%/*}"
  REPO="${owner_repo#*/}"
fi

GH_OK=0
if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
  GH_OK=1
fi

# gh honors CLICOLOR_FORCE even for machine-readable --json output, which
# breaks jq if the caller's shell sets it (e.g. CLICOLOR_FORCE=1). Strip any
# ANSI escapes from captured gh output before it ever reaches jq.
strip_ansi() { sed -E $'s/\x1b\\[[0-9;]*[A-Za-z]//g'; }

# Default branch: origin/HEAD -> gh (if authed) -> main/master -> current branch.
DEFAULT_BRANCH="$(git symbolic-ref --short refs/remotes/origin/HEAD 2>/dev/null | sed 's#^origin/##' || true)"
if [ -z "$DEFAULT_BRANCH" ] && [ "$GH_OK" = 1 ] && [ -n "$OWNER" ]; then
  DEFAULT_BRANCH="$(gh repo view "$OWNER/$REPO" --json defaultBranchRef --jq '.defaultBranchRef.name' 2>/dev/null || true)"
fi
if [ -z "$DEFAULT_BRANCH" ]; then
  if git show-ref --verify --quiet refs/remotes/origin/main; then DEFAULT_BRANCH="main"
  elif git show-ref --verify --quiet refs/remotes/origin/master; then DEFAULT_BRANCH="master"
  else DEFAULT_BRANCH="$(git branch --show-current)"
  fi
fi

DEV_BRANCH=""
if git show-ref --verify --quiet refs/remotes/origin/dev; then DEV_BRANCH="dev"
elif git show-ref --verify --quiet refs/remotes/origin/develop; then DEV_BRANCH="develop"
fi

# Branch protection: protected | none | "unknown (gh unavailable)".
detect_protection() {
  local branch="$1"
  [ -z "$branch" ] && { printf 'n/a'; return; }
  if [ "$GH_OK" != 1 ] || [ -z "$OWNER" ]; then printf 'unknown (gh unavailable)'; return; fi
  local out
  if out="$(gh api "repos/$OWNER/$REPO/branches/$branch/protection" 2>&1 | strip_ansi)"; then
    printf 'protected'
  elif printf '%s' "$out" | grep -q 'HTTP 404'; then
    printf 'none'
  else
    printf 'unknown (gh api error)'
  fi
}
PROTECTION_DEFAULT="$(detect_protection "$DEFAULT_BRANCH")"
PROTECTION_DEV="$(detect_protection "$DEV_BRANCH")"

# Merge settings.
MERGE_SETTINGS=""
if [ "$GH_OK" = 1 ] && [ -n "$OWNER" ]; then
  MERGE_SETTINGS="$(gh repo view "$OWNER/$REPO" --json squashMergeAllowed,mergeCommitAllowed,rebaseMergeAllowed,deleteBranchOnMerge 2>/dev/null | strip_ansi || true)"
fi

# Branch naming observed in history: merge commit subjects + remote branch names.
declare -A PREFIX_COUNTS=( [feat]=0 [feature]=0 [fix]=0 [refactor]=0 [docs]=0 [chore]=0 )
naming_source="$(
  { git log --merges --pretty=%s 2>/dev/null || true
    git branch -r 2>/dev/null | sed -E 's#^[* ]*origin/##' || true
  }
)"
for p in "${!PREFIX_COUNTS[@]}"; do
  PREFIX_COUNTS[$p]="$(printf '%s\n' "$naming_source" | grep -cE "(^|[ /])${p}/" || true)"
done

# Merge pattern of last 30 commits on the default branch.
CC_REGEX='^(feat|fix|docs|style|refactor|perf|test|build|ci|chore|revert)(\([^)]+\))?!?: .+'
default_ref="origin/$DEFAULT_BRANCH"
git show-ref --verify --quiet "refs/remotes/$default_ref" || default_ref="$DEFAULT_BRANCH"
TOTAL_LAST30="$(git log --oneline -30 "$default_ref" 2>/dev/null | grep -c . || true)"
MERGE_LAST30="$(git log --merges --oneline -30 "$default_ref" 2>/dev/null | grep -c . || true)"
SQUASH_LIKE_LAST30="$(git log --no-merges --pretty=%s -30 "$default_ref" 2>/dev/null | grep -cE "$CC_REGEX" || true)"
DIRECT_LAST30=$(( TOTAL_LAST30 - MERGE_LAST30 - SQUASH_LIKE_LAST30 ))
[ "$DIRECT_LAST30" -lt 0 ] && DIRECT_LAST30=0

# Commit style: Conventional Commit share of last 50 subjects.
CC_TOTAL="$(git log --no-merges --pretty=%s -50 "$default_ref" 2>/dev/null | grep -c . || true)"
CC_MATCH="$(git log --no-merges --pretty=%s -50 "$default_ref" 2>/dev/null | grep -cE "$CC_REGEX" || true)"

# CI: workflow names + triggers.
CI_LINES=()
if [ -d .github/workflows ]; then
  for f in .github/workflows/*.yml .github/workflows/*.yaml; do
    [ -f "$f" ] || continue
    name="$(grep -m1 '^name:' "$f" 2>/dev/null | sed -E 's/^name: *//' | tr -d '"'"'"'' || true)"
    [ -z "$name" ] && name="$(basename "$f")"
    triggers="$(grep -oE '^\s*(push|pull_request|workflow_dispatch|schedule|release|issues|issue_comment)\s*:' "$f" 2>/dev/null \
      | sed -E 's/[: ]+//g' | sort -u | paste -sd, - || true)"
    [ -z "$triggers" ] && triggers="unknown"
    CI_LINES+=("$name ($(basename "$f")): $triggers")
  done
fi

# Existing hooks.
HAS_GITHOOKS=0; [ -d .githooks ] && HAS_GITHOOKS=1
HAS_HUSKY=0; [ -d .husky ] && HAS_HUSKY=1
HAS_CLAUDE_HOOKS=0
[ -f .claude/settings.json ] && jq -e '.hooks' .claude/settings.json >/dev/null 2>&1 && HAS_CLAUDE_HOOKS=1
HAS_AGENTS_HOOKS=0; [ -f .agents/hooks.json ] && HAS_AGENTS_HOOKS=1

# PR / issue templates.
HAS_PR_TEMPLATE=0
for p in .github/pull_request_template.md .github/PULL_REQUEST_TEMPLATE.md .github/PULL_REQUEST_TEMPLATE docs/pull_request_template.md; do
  [ -e "$p" ] && HAS_PR_TEMPLATE=1
done
HAS_ISSUE_TEMPLATES=0
[ -d .github/ISSUE_TEMPLATE ] && [ -n "$(ls -A .github/ISSUE_TEMPLATE 2>/dev/null || true)" ] && HAS_ISSUE_TEMPLATES=1

# Package manager & scripts - root first, then one level of subdirectories
# (monorepo-style backend/ frontend/ layouts are common in these repos).
PKG_INFO_LINES=()
shopt -s nullglob
for f in package.json pyproject.toml build.gradle build.gradle.kts \
         */package.json */pyproject.toml */build.gradle */build.gradle.kts; do
  [ -f "$f" ] || continue
  case "$f" in
    */node_modules/*|node_modules/*) continue ;;
  esac
  case "$f" in
    *package.json)
      pm="npm"
      dir_of_f="$(dirname "$f")"
      [ -f "$dir_of_f/pnpm-lock.yaml" ] && pm="pnpm"
      [ -f "$dir_of_f/yarn.lock" ] && pm="yarn"
      scripts="$(jq -r '.scripts // {} | keys | join(",")' "$f" 2>/dev/null || true)"
      PKG_INFO_LINES+=("$f ($pm) - scripts: ${scripts:-none}")
      ;;
    *pyproject.toml)
      PKG_INFO_LINES+=("$f (python, uv)")
      ;;
    *build.gradle*)
      PKG_INFO_LINES+=("$f (gradle)")
      ;;
  esac
done
shopt -u nullglob

# GitHub Project v2 link: skipped - graphql lookup isn't worth the added
# failure surface for a docs-only script; report it as not checked.
GITHUB_PROJECT="not checked (skipped)"

# ---------------------------------------------------------------------------
# File generation helpers
# ---------------------------------------------------------------------------

write_file() { # path content
  local path="$1" content="$2"
  if [ "$DRY_RUN" = 1 ]; then
    note "(dry-run) would create $path"
  else
    mkdir -p "$(dirname "$path")"
    printf '%s' "$content" > "$path"
    note "created $path"
  fi
}

append_file() { # path content
  local path="$1" content="$2"
  if [ "$DRY_RUN" = 1 ]; then
    note "(dry-run) would append to $path"
  else
    printf '%s' "$content" >> "$path"
    note "modified $path"
  fi
}

copy_substituted() { # src dest
  local src="$1" dest="$2"
  if [ "$DRY_RUN" = 1 ]; then
    note "(dry-run) would create $dest"
  else
    mkdir -p "$(dirname "$dest")"
    sed -e "s/{{DATE}}/$DATE/g" -e "s/{{PROJECT}}/$REPO/g" "$src" > "$dest"
    note "created $dest"
  fi
}

skip() { note "skip $1"; } # caller includes the "(reason)" suffix

# ---------------------------------------------------------------------------
# Workflow contract (reality, never claimed enforcement that doesn't exist)
# ---------------------------------------------------------------------------

protection_label() {
  case "$1" in
    protected) printf 'GitHub branch protection' ;;
    none) printf 'nothing (convention only)' ;;
    n/a) printf 'nothing (convention only)' ;;
    *) printf 'unknown - gh not available to check' ;;
  esac
}

if [ -n "$DEV_BRANCH" ]; then
  base_branch_rule="Base branch is \`$DEV_BRANCH\`, \`$DEFAULT_BRANCH\` only moves separately"
  base_branch_enforced="$(protection_label "$PROTECTION_DEV")"
else
  base_branch_rule="Single branch flow - \`$DEFAULT_BRANCH\` is both base and release branch"
  base_branch_enforced="$(protection_label "$PROTECTION_DEFAULT")"
fi

if [ "$MERGE_LAST30" -gt "$DIRECT_LAST30" ] && [ "$MERGE_LAST30" -gt 0 ]; then
  merge_pattern_rule="PRs merged into \`$DEFAULT_BRANCH\` via merge commit ($MERGE_LAST30 of last $TOTAL_LAST30 commits are merges)"
elif [ "$DIRECT_LAST30" -ge "$MERGE_LAST30" ] && [ "$DIRECT_LAST30" -gt 0 ]; then
  merge_pattern_rule="Direct commits to \`$DEFAULT_BRANCH\` observed ($DIRECT_LAST30 of last $TOTAL_LAST30 commits, no PR/merge-commit flow for most of them)"
else
  merge_pattern_rule="Not enough history on \`$DEFAULT_BRANCH\` to tell"
fi
merge_pattern_enforced="nothing (convention only)"
if [ "$PROTECTION_DEFAULT" = "protected" ]; then
  merge_pattern_enforced="GitHub branch protection on \`$DEFAULT_BRANCH\` (see raw protection settings)"
fi

naming_bits=()
for p in feat feature fix refactor docs chore; do
  [ "${PREFIX_COUNTS[$p]:-0}" -gt 0 ] && naming_bits+=("$p/ (${PREFIX_COUNTS[$p]})")
done
if [ "${#naming_bits[@]}" -gt 0 ]; then
  branch_naming_rule="Branch names observed: $(IFS=', '; echo "${naming_bits[*]}")"
else
  branch_naming_rule="No consistent branch naming convention observed"
fi

if [ "$CC_TOTAL" -gt 0 ]; then
  cc_pct=$(( CC_MATCH * 100 / CC_TOTAL ))
  commit_style_rule="~${cc_pct}% of the last $CC_TOTAL commit subjects on \`$DEFAULT_BRANCH\` are Conventional Commits"
else
  commit_style_rule="No commit history to measure commit message style"
  cc_pct=0
fi

if [ "${#CI_LINES[@]}" -gt 0 ]; then
  ci_rule="CI: $(IFS='; '; echo "${CI_LINES[*]}")"
  ci_enforced="nothing requires it to pass before merge"
  if [ "$PROTECTION_DEFAULT" = "protected" ] || [ "$PROTECTION_DEV" = "protected" ]; then
    ci_enforced="GitHub branch protection (if its required checks include a CI job name above)"
  fi
else
  ci_rule="No CI configured"
  ci_enforced="nothing (convention only)"
fi

merge_settings_rule="Merge settings unknown (gh not available)"
if [ -n "$MERGE_SETTINGS" ]; then
  sq="$(printf '%s' "$MERGE_SETTINGS" | jq -r '.squashMergeAllowed')"
  mc="$(printf '%s' "$MERGE_SETTINGS" | jq -r '.mergeCommitAllowed')"
  rb="$(printf '%s' "$MERGE_SETTINGS" | jq -r '.rebaseMergeAllowed')"
  db="$(printf '%s' "$MERGE_SETTINGS" | jq -r '.deleteBranchOnMerge')"
  merge_settings_rule="Repo allows: squash=$sq, merge-commit=$mc, rebase=$rb; delete-branch-on-merge=$db"
fi

WORKFLOW_CONTRACT="$(cat <<EOF
## Workflow contract

These rules describe this repo's CURRENT reality, detected by \`project-init\`'s \`adopt.sh\` on $DATE - not an aspiration. If a row says "nothing (convention only)", that rule is not mechanically enforced today.

| Rule | Documented | Enforced by |
|---|---|---|
| $base_branch_rule | this section | $base_branch_enforced |
| $branch_naming_rule | this section | nothing (convention only) |
| $merge_pattern_rule | this section | $merge_pattern_enforced |
| $commit_style_rule | this section | nothing (convention only) |
| $ci_rule | this section | $ci_enforced |
| $merge_settings_rule | this section | GitHub repo settings (\`gh repo view\`) |

Changing any rule above: update this table and every enforcement point in the same change, and record it in \`docs/decisions/\`.

### Recommended (not enforced yet)
EOF
)"

RECOMMENDATIONS=()
if [ "$PROTECTION_DEFAULT" != "protected" ]; then
  RECOMMENDATIONS+=("Branch protection on \`$DEFAULT_BRANCH\` (required status checks, no force-push).")
fi
if [ "${#CI_LINES[@]}" -eq 0 ]; then
  RECOMMENDATIONS+=("CI that runs lint/typecheck/tests on every PR.")
fi
if [ "$cc_pct" -lt 50 ] && [ "$HAS_PR_TEMPLATE" = 0 ]; then
  RECOMMENDATIONS+=("A PR template and/or Conventional Commit enforcement (commit style is inconsistent today).")
fi
if [ "${#RECOMMENDATIONS[@]}" -eq 0 ]; then
  RECOMMENDATIONS+=("Nothing urgent - protection, CI, and commit style already look reasonable.")
fi
RECOMMENDATIONS=("${RECOMMENDATIONS[@]:0:3}")

for r in "${RECOMMENDATIONS[@]}"; do
  WORKFLOW_CONTRACT="$WORKFLOW_CONTRACT
- $r"
done
WORKFLOW_CONTRACT="$WORKFLOW_CONTRACT
"

# ---------------------------------------------------------------------------
# Documentation map (only entries that exist after adopt - computed last)
# ---------------------------------------------------------------------------

doc_map_entries() {
  local n=1
  printf '%d. `AGENTS.md` (this file) - map, how we work, workflow contract.\n' "$n"; n=$((n+1))
  [ -f .agents/CONTEXT.md ] && { printf '%d. `.agents/CONTEXT.md` - current stack/architecture snapshot and repo facts.\n' "$n"; n=$((n+1)); }
  [ -f docs/plans/HANDOFF.md ] && { printf '%d. `docs/plans/HANDOFF.md` - current state and how to resume, read first if work is mid-flight.\n' "$n"; n=$((n+1)); }
  [ -f docs/architecture.md ] && { printf '%d. `docs/architecture.md` - overview, modules, data model, key flows, env, deploy.\n' "$n"; n=$((n+1)); }
  if [ -d docs/decisions ] && find docs/decisions -maxdepth 1 -iname '*.md' 2>/dev/null | grep -q .; then
    printf '%d. `docs/decisions/` - ADRs: why a non-trivial trade-off was decided the way it was.\n' "$n"; n=$((n+1))
  elif [ -d docs/adr ] && find docs/adr -maxdepth 1 -iname '*.md' 2>/dev/null | grep -q .; then
    printf '%d. `docs/adr/` - ADRs: why a non-trivial trade-off was decided the way it was.\n' "$n"; n=$((n+1))
  fi
  if [ -d docs/superpowers/specs ] || [ -d docs/superpowers/plans ]; then
    printf '%d. `docs/superpowers/specs/` and `docs/superpowers/plans/` - what is being built and how, per unit of work.\n' "$n"; n=$((n+1))
  fi
}

DOC_RULES='## Documentation rules

- Any decision with a real trade-off (architecture, a hard-to-reverse library/service choice, data model, security trade-off) gets a new ADR under the ADR directory above.
- When work pauses mid-flight, update `docs/plans/HANDOFF.md` before stopping, not after.
- A change that alters architecture, env vars, commands, or deploy updates `AGENTS.md` and `.agents/CONTEXT.md` in the same change.
- Changing any "Workflow contract" rule updates every enforcement point in the same change, per that section above.
'

# ---------------------------------------------------------------------------
# .agents/CONTEXT.md - generated before AGENTS.md so its Documentation map
# can already point at it if it was just created.
# ---------------------------------------------------------------------------

readme_first_paragraph() {
  [ -f README.md ] || { printf 'TODO: one or two sentences on what this project does and for whom.'; return; }
  awk '
    /^# / { seen_title=1; next }
    seen_title && NF==0 && buf!="" { exit }
    seen_title && NF>0 { buf = buf $0 " " }
    END { print buf }
  ' README.md | sed -E 's/\s+$//'
}

stack_section() {
  if [ "${#PKG_INFO_LINES[@]}" -eq 0 ]; then
    printf '_Not detected automatically - fill in._\n'
    return
  fi
  local line
  for line in "${PKG_INFO_LINES[@]}"; do
    printf -- '- %s\n' "$line"
  done
}

if [ -f .agents/CONTEXT.md ]; then
  skip ".agents/CONTEXT.md (exists)"
else
  flow_summary="Single branch flow on \`$DEFAULT_BRANCH\`."
  [ -n "$DEV_BRANCH" ] && flow_summary="Base branch is \`$DEV_BRANCH\`; \`$DEFAULT_BRANCH\` is separate."
  context_content="# $REPO - Repository Context

## Purpose

$(readme_first_paragraph)

## Stack

$(stack_section)

## Commands

See AGENTS.md for detected commands.

## Repo facts

- Owner: ${OWNER:-unknown}
- Base branch: \`$DEFAULT_BRANCH\`. $flow_summary See \"Workflow contract\" in AGENTS.md for the full picture and what's actually enforced.

Last validated: $DATE
"
  write_file ".agents/CONTEXT.md" "$context_content"
fi

# ---------------------------------------------------------------------------
# docs/decisions (ADRs) - reuse an existing ADR folder if the repo has one.
# ---------------------------------------------------------------------------

if [ -d docs/adr ] && find docs/adr -maxdepth 1 -iname '*.md' 2>/dev/null | grep -q .; then
  skip "docs/decisions (repo already uses docs/adr/ with existing ADRs)"
elif [ -d docs/decisions ] && find docs/decisions -maxdepth 1 -iname '*.md' 2>/dev/null | grep -q .; then
  skip "docs/decisions (already has ADRs)"
else
  copy_substituted "$COMMON_DECISIONS_DIR/0000-template.md" "docs/decisions/0000-template.md"
  copy_substituted "$COMMON_DECISIONS_DIR/0001-record-architecture-decisions.md" "docs/decisions/0001-record-architecture-decisions.md"
fi

# ---------------------------------------------------------------------------
# docs/plans/HANDOFF.md
# ---------------------------------------------------------------------------

if [ -f docs/plans/HANDOFF.md ]; then
  skip "docs/plans/HANDOFF.md (exists)"
else
  handoff_content="# Handoff - $REPO

Last updated: $DATE

## Current state

<!-- One or two sentences: what's built/working right now, and what isn't yet. -->

Adopted into the documentation layer by \`project-init\`'s adopt mode on $DATE - fill in the real current state.

## Active plan

<!-- Link the plan this work is following, if any. -->

None yet.

## Pending work

<!-- Concrete next steps, in the order they should happen. Delete items as
     they're done instead of checking them off, so this list only ever
     shows what's left. -->

## How to resume

1. Read \`AGENTS.md\`, then \`.agents/CONTEXT.md\`.
2. Check \`docs/decisions/\` for any ADR relevant to the area you're about to touch.
3. Pick up \"Pending work\" from the top.
"
  write_file "docs/plans/HANDOFF.md" "$handoff_content"
fi

# ---------------------------------------------------------------------------
# AGENTS.md / CLAUDE.md
# ---------------------------------------------------------------------------

AGENTS_EXISTED=0; [ -f AGENTS.md ] && AGENTS_EXISTED=1
CLAUDE_EXISTED=0; [ -f CLAUDE.md ] && CLAUDE_EXISTED=1

has_real_content() {
  local f="$1"
  [ -f "$f" ] || { printf 0; return; }
  local nonempty import real
  nonempty="$(grep -vcE '^\s*$' "$f" || true)"
  import="$(grep -cE '^@\S' "$f" || true)"
  real=$(( nonempty - import ))
  [ "$real" -gt 1 ] && printf 1 || printf 0
}
CLAUDE_HAS_REAL_CONTENT=0
[ "$CLAUDE_EXISTED" = 1 ] && CLAUDE_HAS_REAL_CONTENT="$(has_real_content CLAUDE.md)"

commands_section() {
  if [ "${#PKG_INFO_LINES[@]}" -eq 0 ]; then
    printf '_No package manifest detected._\n'
    return
  fi
  local line
  for line in "${PKG_INFO_LINES[@]}"; do
    printf -- '- `%s`\n' "$line"
  done
}

CLAUDE_HANDLED=0

if [ "$AGENTS_EXISTED" = 0 ] && [ "$CLAUDE_EXISTED" = 1 ] && [ "$CLAUDE_HAS_REAL_CONTENT" = 1 ]; then
  # CLAUDE.md carries this repo's real notes and there is no AGENTS.md yet:
  # move that content into AGENTS.md (the single source of truth), replace
  # CLAUDE.md with a thin pointer plus any clearly Claude-only lines.
  claude_body="$(cat CLAUDE.md)"
  claude_only_lines="$(grep -iE 'claude' CLAUDE.md || true)"

  agents_content="# AGENTS.md

Single source of truth for humans and AI agents working on this repo. Moved here from CLAUDE.md on $DATE by \`project-init\`'s adopt mode - if this file and the code disagree, the code wins, fix this file.

## Documentation map (read this instead of the code)

$(doc_map_entries)

$claude_body

$WORKFLOW_CONTRACT

$DOC_RULES"
  write_file "AGENTS.md" "$agents_content"
  AGENTS_EXISTED=1

  claude_pointer="@AGENTS.md
"
  if [ -n "$claude_only_lines" ]; then
    claude_pointer="$claude_pointer
# Claude-only notes

$claude_only_lines
"
  fi
  write_file "CLAUDE.md" "$claude_pointer"
  CLAUDE_HANDLED=1
elif [ "$AGENTS_EXISTED" = 0 ]; then
  agents_content="# AGENTS.md

Single source of truth for humans and AI agents (Codex, Cursor, Claude, others) working on **$REPO**. If this file and the code disagree, the code wins - fix this file.

## Documentation map (read this instead of the code)

$(doc_map_entries)

## Purpose

$(readme_first_paragraph)

## Stack

$(stack_section)

## Commands

$(commands_section)

$WORKFLOW_CONTRACT

$DOC_RULES"
  write_file "AGENTS.md" "$agents_content"
else
  if grep -q '^## Workflow contract' AGENTS.md 2>/dev/null || grep -q '^# Workflow contract' AGENTS.md 2>/dev/null; then
    skip "AGENTS.md (already has a Workflow contract section)"
  else
    append=""
    if ! grep -q '^## Documentation map' AGENTS.md 2>/dev/null; then
      append="$append

## Documentation map (read this instead of the code)

$(doc_map_entries)"
    fi
    append="$append

$WORKFLOW_CONTRACT"
    if ! grep -q '^## Documentation rules' AGENTS.md 2>/dev/null; then
      append="$append

$DOC_RULES"
    fi
    append_file "AGENTS.md" "$append"
  fi
fi

if [ "$CLAUDE_HANDLED" = 0 ]; then
  if [ "$CLAUDE_EXISTED" = 0 ]; then
    claude_content="@AGENTS.md
"
    [ -f .agents/CONTEXT.md ] && claude_content="$claude_content@.agents/CONTEXT.md
"
    write_file "CLAUDE.md" "$claude_content"
  else
    if [ "$CLAUDE_HAS_REAL_CONTENT" = 1 ] && ! grep -q '^@AGENTS\.md' CLAUDE.md 2>/dev/null; then
      deviation "CLAUDE.md has its own content and does not import AGENTS.md - left untouched to avoid losing content. Review by hand: merge into AGENTS.md and replace CLAUDE.md with @AGENTS.md."
      skip "CLAUDE.md (has own content, left for manual review)"
    else
      skip "CLAUDE.md (exists)"
    fi
  fi
fi

# ---------------------------------------------------------------------------
# Report
# ---------------------------------------------------------------------------

if [ "$JSON" = 1 ]; then
  jq -n \
    --arg owner "$OWNER" \
    --arg repo "$REPO" \
    --arg default_branch "$DEFAULT_BRANCH" \
    --arg dev_branch "$DEV_BRANCH" \
    --arg protection_default "$PROTECTION_DEFAULT" \
    --arg protection_dev "$PROTECTION_DEV" \
    --argjson merge_settings "${MERGE_SETTINGS:-null}" \
    --arg commit_conventional_pct "$cc_pct" \
    --arg commit_sample_size "$CC_TOTAL" \
    --argjson ci "$(printf '%s\n' "${CI_LINES[@]:-}" | jq -R . | jq -s 'map(select(length > 0))')" \
    --argjson hooks "$(jq -n --argjson githooks "$([ "$HAS_GITHOOKS" = 1 ] && echo true || echo false)" \
                             --argjson husky "$([ "$HAS_HUSKY" = 1 ] && echo true || echo false)" \
                             --argjson claude_settings "$([ "$HAS_CLAUDE_HOOKS" = 1 ] && echo true || echo false)" \
                             --argjson agents_hooks_json "$([ "$HAS_AGENTS_HOOKS" = 1 ] && echo true || echo false)" \
                             '{githooks:$githooks, husky:$husky, claude_settings:$claude_settings, agents_hooks_json:$agents_hooks_json}')" \
    --argjson pr_template "$([ "$HAS_PR_TEMPLATE" = 1 ] && echo true || echo false)" \
    --argjson issue_templates "$([ "$HAS_ISSUE_TEMPLATES" = 1 ] && echo true || echo false)" \
    --arg github_project "$GITHUB_PROJECT" \
    --argjson packages "$(printf '%s\n' "${PKG_INFO_LINES[@]:-}" | jq -R . | jq -s 'map(select(length > 0))')" \
    --argjson actions "$(printf '%s\n' "${ACTIONS[@]:-}" | jq -R . | jq -s 'map(select(length > 0))')" \
    --argjson recommendations "$(printf '%s\n' "${RECOMMENDATIONS[@]:-}" | jq -R . | jq -s 'map(select(length > 0))')" \
    --argjson deviations "$(printf '%s\n' "${DEVIATIONS[@]:-}" | jq -R . | jq -s 'map(select(length > 0))')" \
    --argjson dry_run "$([ "$DRY_RUN" = 1 ] && echo true || echo false)" \
    '{
      owner: $owner, repo: $repo,
      default_branch: $default_branch,
      dev_branch: (if $dev_branch == "" then null else $dev_branch end),
      branch_protection: { default: $protection_default, dev: $protection_dev },
      merge_settings: $merge_settings,
      commit_style: { conventional_pct: ($commit_conventional_pct | tonumber), sample_size: ($commit_sample_size | tonumber) },
      ci: $ci,
      hooks: $hooks,
      pr_template: $pr_template,
      issue_templates: $issue_templates,
      github_project: $github_project,
      packages: $packages,
      dry_run: $dry_run,
      actions: $actions,
      recommendations: $recommendations,
      deviations: $deviations
    }'
else
  echo "== adopt.sh: $OWNER/$REPO =="
  echo "Default branch: $DEFAULT_BRANCH"
  [ -n "$DEV_BRANCH" ] && echo "Dev branch: $DEV_BRANCH (exists on origin)" || echo "Dev branch: none"
  echo "Branch protection: $DEFAULT_BRANCH=$PROTECTION_DEFAULT, $([ -n "$DEV_BRANCH" ] && echo "$DEV_BRANCH=$PROTECTION_DEV" || echo "n/a")"
  [ -n "$MERGE_SETTINGS" ] && echo "Merge settings: $merge_settings_rule"
  echo "Branch naming: $branch_naming_rule"
  echo "Merge pattern (last $TOTAL_LAST30 on $DEFAULT_BRANCH): $merge_pattern_rule"
  echo "Commit style: $commit_style_rule"
  if [ "${#CI_LINES[@]}" -gt 0 ]; then
    printf 'CI: %s\n' "${CI_LINES[@]}"
  else
    echo "CI: none"
  fi
  echo "PR template: $([ "$HAS_PR_TEMPLATE" = 1 ] && echo yes || echo no); Issue templates: $([ "$HAS_ISSUE_TEMPLATES" = 1 ] && echo yes || echo no)"
  echo "Hooks: githooks=$([ "$HAS_GITHOOKS" = 1 ] && echo yes || echo no) husky=$([ "$HAS_HUSKY" = 1 ] && echo yes || echo no) claude-settings=$([ "$HAS_CLAUDE_HOOKS" = 1 ] && echo yes || echo no) agents-hooks=$([ "$HAS_AGENTS_HOOKS" = 1 ] && echo yes || echo no)"
  echo "GitHub Project: $GITHUB_PROJECT"
  if [ "${#PKG_INFO_LINES[@]}" -gt 0 ]; then
    printf 'Packages: %s\n' "${PKG_INFO_LINES[@]}"
  fi
  echo
  echo "--- Generated Workflow contract ---"
  printf '%s\n' "$WORKFLOW_CONTRACT"
  echo "--- Actions ---"
  if [ "${#ACTIONS[@]}" -gt 0 ]; then
    printf '%s\n' "${ACTIONS[@]}"
  else
    echo "(none)"
  fi
  if [ "${#DEVIATIONS[@]}" -gt 0 ]; then
    echo "--- Deviations (manual review needed) ---"
    printf '%s\n' "${DEVIATIONS[@]}"
  fi
  echo "--- Recommended (not enforced yet) ---"
  printf '%s\n' "${RECOMMENDATIONS[@]}"
fi
